//! The federation's threshold BIP340 invoice signing key.
//!
//! The key is generated by FROST distributed key generation during federation
//! setup. Round-two packages are secret shares; they are encrypted to each
//! recipient before they enter the broadcast-style exchange the setup ceremony
//! offers, and bound to the transcript so they cannot be replayed elsewhere.

use std::collections::{BTreeMap, BTreeSet};

use anyhow::{Context, Result, ensure};
use chacha20poly1305::aead::{Aead, KeyInit, Payload};
use chacha20poly1305::{ChaCha20Poly1305, Nonce};
use fedimint_bolt12_common::bolt12::{
    Bolt12Config, MAX_POOL_BATCH, MAX_POOL_DEGREE, MAX_POOL_TARGET, PoolRun, quorum,
};
use fedimint_bolt12_common::config::{Bolt12ModuleConfig, Bolt12PrivateConfig};
use fedimint_core::PeerId;
use fedimint_core::bitcoin::hashes::{Hash, sha256};
use fedimint_core::encoding::Encodable;
use fedimint_core::secp256k1::{PublicKey, SECP256K1, SecretKey, ecdh};
use fedimint_server_core::config::PeerHandleOps;
use frost_secp256k1_tr as frost;
use rand::rngs::OsRng;
use serde::{Deserialize, Serialize};

/// Set while generating configuration to enable federated BOLT12 receives.
pub const FM_ENABLE_FEDERATED_BOLT12_ENV: &str = "FM_ENABLE_FEDERATED_BOLT12";
/// Optional override for `Bolt12Config::pool_target` during federation setup.
pub const FM_BOLT12_POOL_TARGET_ENV: &str = "FM_BOLT12_POOL_TARGET";
/// Optional override for `Bolt12Config::pool_batch` during federation setup.
pub const FM_BOLT12_POOL_BATCH_ENV: &str = "FM_BOLT12_POOL_BATCH";

fn parse_env_u64(name: &str, default: u64) -> Result<u64> {
    match std::env::var(name) {
        Ok(raw) => raw
            .parse::<u64>()
            .with_context(|| format!("invalid {name} value: {raw:?}")),
        Err(std::env::VarError::NotPresent) => Ok(default),
        Err(err) => Err(err).with_context(|| format!("failed to read {name}")),
    }
}

/// Fewer guardians cannot tolerate a single fault.
const MIN_GUARDIANS: usize = 4;

/// The FROST participant identifier of a guardian. Identifiers are nonzero.
pub fn identifier(peer: PeerId) -> Result<frost::Identifier> {
    Ok(frost::Identifier::try_from(
        u16::from(peer)
            .checked_add(1)
            .context("guardian identifier overflow")?,
    )?)
}

fn parameters(guardians: usize) -> Result<(u16, u16)> {
    ensure!(
        guardians >= MIN_GUARDIANS,
        "federated BOLT12 requires at least four guardians"
    );

    Ok((u16::try_from(guardians)?, u16::try_from(quorum(guardians))?))
}

fn config(
    guardians: usize,
    public: &frost::keys::PublicKeyPackage,
    transport_keys: BTreeMap<PeerId, PublicKey>,
) -> Result<Bolt12Config> {
    let pool_target = if PoolRun::degree(guardians) <= MAX_POOL_DEGREE {
        let target = parse_env_u64(FM_BOLT12_POOL_TARGET_ENV, Bolt12Config::DEFAULT_POOL_TARGET)?;
        ensure!(
            target <= MAX_POOL_TARGET,
            "{FM_BOLT12_POOL_TARGET_ENV} ({target}) exceeds MAX_POOL_TARGET ({MAX_POOL_TARGET})"
        );
        target
    } else {
        0
    };
    let pool_batch = parse_env_u64(FM_BOLT12_POOL_BATCH_ENV, Bolt12Config::DEFAULT_POOL_BATCH)?;
    ensure!(
        (1..=MAX_POOL_BATCH).contains(&pool_batch),
        "{FM_BOLT12_POOL_BATCH_ENV} ({pool_batch}) must be in 1..={MAX_POOL_BATCH}"
    );

    Ok(Bolt12Config {
        signing_key: PublicKey::from_slice(&public.verifying_key().serialize()?)?,
        public_package: public.serialize()?,
        transport_keys,
        registration_fee: Bolt12Config::DEFAULT_REGISTRATION_FEE,
        stock_item_fee: Bolt12Config::DEFAULT_STOCK_ITEM_FEE,
        receive_fee: Bolt12Config::DEFAULT_RECEIVE_FEE,
        pool_fee: Bolt12Config::DEFAULT_POOL_FEE,
        pool_target,
        pool_batch,
    })
}

fn ensure_distinct_xonly_keys(transport_keys: &BTreeMap<PeerId, PublicKey>) -> Result<()> {
    let mut xonly = BTreeSet::new();

    for key in transport_keys.values() {
        ensure!(
            xonly.insert(key.x_only_public_key().0),
            "BOLT12 transport keys must have pairwise distinct x-only public keys"
        );
    }

    Ok(())
}

/// Trusted-dealer keys for test fixtures. Production setup uses [`generate`].
pub fn fixture(peers: &[PeerId]) -> Result<(Bolt12Config, BTreeMap<PeerId, Bolt12PrivateConfig>)> {
    let (max_signers, min_signers) = parameters(peers.len())?;

    let identifiers = peers
        .iter()
        .map(|peer| identifier(*peer))
        .collect::<Result<Vec<_>>>()?;

    let (shares, public) = frost::keys::generate_with_dealer(
        max_signers,
        min_signers,
        frost::keys::IdentifierList::Custom(&identifiers),
        OsRng,
    )?;

    let mut private = BTreeMap::new();
    let mut transport_keys = BTreeMap::new();

    for peer in peers {
        let transport_secret = SecretKey::new(&mut OsRng);
        let share = shares
            .get(&identifier(*peer)?)
            .context("dealer omitted a guardian")?
            .clone();

        transport_keys.insert(*peer, transport_secret.public_key(SECP256K1));
        private.insert(
            *peer,
            Bolt12PrivateConfig {
                key_package: frost::keys::KeyPackage::try_from(share)?.serialize()?,
                transport_secret,
            },
        );
    }

    Ok((config(peers.len(), &public, transport_keys)?, private))
}

/// A symmetric key for one direction of one guardian pair in one context.
pub fn transport_key(secret: &SecretKey, peer: &PublicKey, domain: &[u8]) -> [u8; 32] {
    let shared = ecdh::SharedSecret::new(peer, secret);

    (
        "fedimint/bolt12/channel/v1",
        shared.secret_bytes(),
        domain.to_vec(),
    )
        .consensus_hash::<sha256::Hash>()
        .to_byte_array()
}

#[derive(Serialize, Deserialize)]
struct EncryptedPackage {
    recipient: PeerId,
    nonce: [u8; 12],
    ciphertext: Vec<u8>,
}

/// Exchange `value` and require every guardian to have sent the same bytes.
/// This turns the exchange into an agreement check on a transcript hash.
async fn agree(
    peers: &(dyn PeerHandleOps + Send + Sync),
    value: &[u8],
    what: &'static str,
) -> Result<()> {
    let echoes = peers.exchange_bytes(value.to_vec()).await?;

    ensure!(
        echoes.values().all(|echo| echo.as_slice() == value),
        "guardians disagree about {what}"
    );

    Ok(())
}

fn package_domain(transcript: sha256::Hash, sender: PeerId, recipient: PeerId) -> Vec<u8> {
    (
        "fedimint/bolt12/dkg-round2/v1",
        transcript,
        sender,
        recipient,
    )
        .consensus_encode_to_vec()
}

/// Run FROST distributed key generation with the other guardians.
pub async fn generate(
    peers: &(dyn PeerHandleOps + Send + Sync),
) -> Result<(Bolt12Config, Bolt12PrivateConfig)> {
    let guardians = peers.num_peers().total();
    let (max_signers, min_signers) = parameters(guardians)?;

    // Fresh identities for private guardian channels. Every guardian must see
    // the same set, or an encrypted package could be readable by an impostor.
    let transport_secret = SecretKey::new(&mut OsRng);
    let transport_public = transport_secret.public_key(SECP256K1);

    let transport_keys = peers
        .exchange_bytes(transport_public.serialize().to_vec())
        .await?
        .iter()
        .map(|(peer, bytes)| Ok((*peer, PublicKey::from_slice(bytes)?)))
        .collect::<Result<BTreeMap<_, _>>>()?;

    let mut ours = transport_keys
        .iter()
        .filter(|(_, key)| **key == transport_public);
    let me = *ours.next().context("our transport key is missing")?.0;

    ensure!(ours.next().is_none(), "duplicate transport key");
    ensure_distinct_xonly_keys(&transport_keys)?;

    let keys_view: sha256::Hash = ("fedimint/bolt12/dkg-keys/v1", &transport_keys).consensus_hash();

    agree(peers, keys_view.as_byte_array(), "transport keys").await?;

    let (round_one_secret, round_one) =
        frost::keys::dkg::part1(identifier(me)?, max_signers, min_signers, OsRng)?;

    let round_one_wire = peers.exchange_bytes(round_one.serialize()?).await?;

    let transcript: sha256::Hash =
        ("fedimint/bolt12/dkg-round1/v1", keys_view, &round_one_wire).consensus_hash();

    agree(peers, transcript.as_byte_array(), "round-one packages").await?;

    let round_one_packages = round_one_wire
        .iter()
        .filter(|(peer, _)| **peer != me)
        .map(|(peer, bytes)| {
            Ok((
                identifier(*peer)?,
                frost::keys::dkg::round1::Package::deserialize(bytes)?,
            ))
        })
        .collect::<Result<BTreeMap<_, _>>>()?;

    let (round_two_secret, round_two) =
        frost::keys::dkg::part2(round_one_secret, &round_one_packages)?;

    let mut outgoing = Vec::new();

    for (peer, key) in transport_keys.iter().filter(|(peer, _)| **peer != me) {
        let domain = package_domain(transcript, me, *peer);
        let nonce: [u8; 12] = rand::random();

        let package = round_two
            .get(&identifier(*peer)?)
            .context("missing round-two package")?
            .serialize()?;

        // The key is unique to this transcript and direction, so a random
        // nonce cannot collide with another message under the same key.
        let ciphertext =
            ChaCha20Poly1305::new((&transport_key(&transport_secret, key, &domain)).into())
                .encrypt(
                    Nonce::from_slice(&nonce),
                    Payload {
                        msg: &package,
                        aad: &domain,
                    },
                )
                .map_err(|_| anyhow::anyhow!("round-two encryption failed"))?;

        outgoing.push(EncryptedPackage {
            recipient: *peer,
            nonce,
            ciphertext,
        });
    }

    let incoming = peers.exchange_bytes(serde_json::to_vec(&outgoing)?).await?;

    let mut round_two_packages = BTreeMap::new();

    for (sender, wire) in incoming.iter().filter(|(peer, _)| **peer != me) {
        let packages: Vec<EncryptedPackage> = serde_json::from_slice(wire)?;

        ensure!(
            packages.len() == guardians - 1,
            "wrong number of round-two packages"
        );

        let mut mine = packages.iter().filter(|package| package.recipient == me);
        let package = mine.next().context("missing round-two package for us")?;

        ensure!(mine.next().is_none(), "duplicate round-two package for us");

        let domain = package_domain(transcript, *sender, me);
        let key = transport_key(&transport_secret, &transport_keys[sender], &domain);

        let clear = ChaCha20Poly1305::new((&key).into())
            .decrypt(
                Nonce::from_slice(&package.nonce),
                Payload {
                    msg: &package.ciphertext,
                    aad: &domain,
                },
            )
            .map_err(|_| anyhow::anyhow!("round-two package failed authentication"))?;

        round_two_packages.insert(
            identifier(*sender)?,
            frost::keys::dkg::round2::Package::deserialize(&clear)?,
        );
    }

    let (key_package, public) =
        frost::keys::dkg::part3(&round_two_secret, &round_one_packages, &round_two_packages)?;

    let config = config(guardians, &public, transport_keys)?;

    agree_config(peers, &config).await?;

    Ok((
        config,
        Bolt12PrivateConfig {
            key_package: key_package.serialize()?,
            transport_secret,
        },
    ))
}

async fn agree_config(
    peers: &(dyn PeerHandleOps + Send + Sync),
    config: &Bolt12Config,
) -> Result<()> {
    let view: sha256::Hash = (
        "fedimint/bolt12/dkg-config/v1",
        &config.public_package,
        config.pool_target,
        config.pool_batch,
    )
        .consensus_hash();
    agree(
        peers,
        view.as_byte_array(),
        "the signing key and pool configuration",
    )
    .await
}

/// Check that a guardian's BOLT12 configuration is internally consistent.
pub fn validate(identity: PeerId, config: &Bolt12ModuleConfig) -> Result<()> {
    let public = &config.consensus.bolt12;
    let private = &config.private.bolt12;

    let guardians = config.consensus.tpe_pks.len();
    let (_, min_signers) = parameters(guardians)?;

    ensure!(
        public
            .transport_keys
            .keys()
            .eq(config.consensus.tpe_pks.keys()),
        "BOLT12 transport keys do not match the guardian set"
    );
    ensure!(
        public.transport_keys.get(&identity)
            == Some(&private.transport_secret.public_key(SECP256K1)),
        "BOLT12 transport secret does not match our public key"
    );
    ensure_distinct_xonly_keys(&public.transport_keys)?;
    ensure!(
        public.pool_target <= MAX_POOL_TARGET && (1..=MAX_POOL_BATCH).contains(&public.pool_batch),
        "BOLT12 pool target or batch is out of range"
    );

    if public.pool_target > 0 {
        let degree = PoolRun::degree(guardians);
        ensure!(
            degree <= MAX_POOL_DEGREE,
            "BOLT12 pool generation requires federation degree <= {MAX_POOL_DEGREE}"
        );
        let params = mpc::engine::Params::new(PoolRun::committee_size(guardians), degree)?;
        let batch = usize::try_from(public.pool_batch)?;
        mpc::direct::circuit(params, batch)?;
    }

    let key = frost::keys::KeyPackage::deserialize(&private.key_package)?;
    let package = frost::keys::PublicKeyPackage::deserialize(&public.public_package)?;

    ensure!(
        *key.identifier() == identifier(identity)?,
        "BOLT12 signing share belongs to another guardian"
    );
    ensure!(
        package.verifying_shares().len() == guardians,
        "BOLT12 signing shares do not match the guardian set"
    );

    for peer in config.consensus.tpe_pks.keys() {
        ensure!(
            package.verifying_shares().contains_key(&identifier(*peer)?),
            "BOLT12 signing share missing for a guardian"
        );
    }

    ensure!(
        public.signing_key == PublicKey::from_slice(&package.verifying_key().serialize()?)?,
        "BOLT12 signing key does not match its key package"
    );
    ensure!(
        key.verifying_key() == package.verifying_key(),
        "BOLT12 signing share is for another key"
    );
    ensure!(
        package.verifying_shares().get(key.identifier()) == Some(key.verifying_share()),
        "BOLT12 verification share mismatch"
    );
    ensure!(
        *key.min_signers() == min_signers,
        "BOLT12 signing threshold is not the guardian quorum"
    );

    Ok(())
}

